  /// Translate Kannada text → current language using reverse lookup
  static String tr(String text) {
    if (current == 'kn') return text;
    // Reverse lookup: find the key whose 'kn' value == text
    final knMap = _allStrings['kn'];
    if (knMap == null) return text;
    for (final entry in knMap.entries) {
      if (entry.value == text) {
        return l(entry.key);
      }
    }
    return text; // no match — return original
  }
}

/// Shorthand global function
String tr(String text) => AppLocale.tr(text);

/// Comprehensive translator: checks tr() + translateKn() + word-by-word fallback
String trAll(String knText) {
  if (AppLocale.current == 'kn') return knText;
  // Direct tr() lookup first (common.dart keys)
  final exact = tr(knText);
  if (exact != knText) return exact;
  // Try translateKn() for array-based data (rashi, tithi, nakshatra, etc.)
  final arrayMatch = translateKn(knText);
  if (arrayMatch != knText) return arrayMatch;
  // Word-by-word for compound strings (e.g. "ನಿಜ ವೈಶಾಖ", "ಪ್ರಭವ (ಶಕ 1948)")
  final words = knText.split(' ');
  if (words.length > 1) {
    return words.map((w) {
      if (RegExp(r'^[\d()°\x27".\-:]+$').hasMatch(w)) return w;
      // Strip leading/trailing punctuation for lookup, re-attach after
      final leadMatch = RegExp(r'^([(\[{]*)(.*)$').firstMatch(w);
      final trailMatch = RegExp(r'^(.*?)([)\]},.:!?]*)$').firstMatch(leadMatch?.group(2) ?? w);
      final prefix = leadMatch?.group(1) ?? '';
      final core = trailMatch?.group(1) ?? w;
      final suffix = trailMatch?.group(2) ?? '';
      if (core.isEmpty) return w;
      // Try tr() first, then translateKn()
      final t = tr(core);
      if (t != core) return '$prefix$t$suffix';
      final tk = translateKn(core);
      if (tk != core) return '$prefix$tk$suffix';
      return w;
    }).join(' ');
  }
  return knText;
}


